const STORAGE_KEY = 'notepad-content';
const STORAGE_TIME_KEY = 'notepad-saved-at';

let hasUnsavedChanges = false;

function onBeforeUnload(e) {
    if (hasUnsavedChanges) {
        e.preventDefault();
    }
}

export function initialize() {
    const content = localStorage.getItem(STORAGE_KEY) ?? '';
    const savedAt = localStorage.getItem(STORAGE_TIME_KEY) ?? '';
    window.addEventListener('beforeunload', onBeforeUnload);
    return { content, savedAt };
}

export function save(content) {
    const now = new Date().toLocaleTimeString([], { hour12: false });
    localStorage.setItem(STORAGE_KEY, content);
    localStorage.setItem(STORAGE_TIME_KEY, now);
    hasUnsavedChanges = false;
    return now;
}

export function clearStorage() {
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(STORAGE_TIME_KEY);
    hasUnsavedChanges = false;
}

export function setDirty(dirty) {
    hasUnsavedChanges = dirty;
}

export function dispose() {
    window.removeEventListener('beforeunload', onBeforeUnload);
}

