+using Microsoft.JSInterop;
+
+namespace sv_99ec793739c046cdb8f1241f4800bf64.Components.Pages;
+
+public sealed class NotepadInterop : IAsyncDisposable
+{
+    internal const string ModulePath = "./Components/Pages/Notepad.razor.js";
+    internal const string InitializeMethod = "initialize";
+    internal const string SaveMethod = "save";
+    internal const string ClearStorageMethod = "clearStorage";
+    internal const string SetDirtyMethod = "setDirty";
+    internal const string DisposeMethod = "dispose";
+
+    private readonly IJSRuntime _js;
+    private IJSObjectReference? _module;
+
+    public NotepadInterop(IJSRuntime js) => _js = js;
+
+    private async ValueTask<IJSObjectReference> GetModuleAsync()
+        => _module ??= await _js.InvokeAsync<IJSObjectReference>("import", ModulePath);
+
+    public async ValueTask<NotepadState> InitializeAsync()
+    {
+        var module = await GetModuleAsync();
+        return await module.InvokeAsync<NotepadState>(InitializeMethod);
+    }
+
+    public async ValueTask<string> SaveAsync(string content)
+    {
+        var module = await GetModuleAsync();
+        return await module.InvokeAsync<string>(SaveMethod, content);
+    }
+
+    public async ValueTask ClearStorageAsync()
+    {
+        var module = await GetModuleAsync();
+        await module.InvokeVoidAsync(ClearStorageMethod);
+    }
+
+    public async ValueTask SetDirtyAsync(bool dirty)
+    {
+        var module = await GetModuleAsync();
+        await module.InvokeVoidAsync(SetDirtyMethod, dirty);
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        try
+        {
+            if (_module is not null)
+            {
+                await _module.InvokeVoidAsync(DisposeMethod);
+                await _module.DisposeAsync();
+            }
+        }
+        catch (JSDisconnectedException) { }
+    }
+}
+
+public record NotepadState(string Content, string SavedAt);
