@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<div class="notepad-container">
    <textarea class="form-control notepad-textarea"
              @bind="Content"
              @bind:event="oninput"
              @bind:after="OnContentChanged"
              placeholder="Type your notes here…"></textarea>

    <div class="notepad-toolbar">
        <span class="notepad-status text-muted">
            @if (!string.IsNullOrEmpty(_lastSavedAt))
            {
                <text>Last saved at @_lastSavedAt</text>
            }
        </span>
        <div>
            <button class="btn btn-outline-danger btn-sm" @onclick="ClearAsync">Clear</button>
            <button class="btn btn-primary btn-sm" @onclick="SaveNowAsync">Save now</button>
        </div>
    </div>
</div>

@code {
    private string Content { get; set; } = string.Empty;

    private string _lastSavedAt = string.Empty;
    private string _savedContent = string.Empty;
    private NotepadInterop? _interop;
    private System.Threading.Timer? _autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            var state = await _interop.InitializeAsync();

            Content = state.Content;
            _savedContent = state.Content;
            _lastSavedAt = state.SavedAt;
            StateHasChanged();

            _autoSaveTimer = new System.Threading.Timer(
                AutoSaveCallback, null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));
        }
    }

    private async Task OnContentChanged()
    {
        bool dirty = Content != _savedContent;
        if (_interop is not null)
        {
            await _interop.SetDirtyAsync(dirty);
        }
    }

    private async void AutoSaveCallback(object? state)
    {
        if (Content != _savedContent && _interop is not null)
        {
            await InvokeAsync(async () =>
            {
                await SaveCoreAsync();
                StateHasChanged();
            });
        }
    }

    private async Task SaveNowAsync()
    {
        if (_interop is not null)
        {
            await SaveCoreAsync();
        }
    }

    private async Task SaveCoreAsync()
    {
        if (_interop is null) return;
        _lastSavedAt = await _interop.SaveAsync(Content);
        _savedContent = Content;
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;
        Content = string.Empty;
        _savedContent = string.Empty;
        _lastSavedAt = string.Empty;
        await _interop.ClearStorageAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
        {
            await _autoSaveTimer.DisposeAsync();
        }

        if (_interop is not null)
        {
            await _interop.DisposeAsync();
        }
    }
}

